def check_available(stock, sku, qty):
    """Raise ValueError if there are fewer than qty of sku in stock."""
    if stock.get(sku, 0) < qty:
        raise ValueError(f"not enough {sku} in stock")


def apply_sale(stock, sku, qty):
    """Return new stock counts after a sale. The input is left as it was."""
    check_available(stock, sku, qty)
    updated = dict(stock)
    updated[sku] -= qty
    return updated

